def fuzzy_match(str1, str2, threshold=0.85):
    s1 = str1.lower().strip()
    s2 = str2.lower().strip()
    if s1 == s2:
        return True
    ratio = SequenceMatcher(None, s1, s2).ratio()
    if ratio >= threshold:
        return True
    return False
